// Deserialize wire names only: serde's enum visitor also accepts numeric
// variant indices in MessagePack, which are not stable wire identities.
impl<'de> serde::Deserialize<'de> for OpKind {
    fn deserialize<D: serde::Deserializer<'de>>(decoder: D) -> Result<Self, D::Error> {
        struct WireKindVisitor;
        impl<'de> serde::de::Visitor<'de> for WireKindVisitor {
            type Value = OpKind;
            fn expecting(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                f.write_str("a SimpleIR wire kind spelling")
            }
            fn visit_str<E: serde::de::Error>(self, input: &str) -> Result<Self::Value, E> {
                input.parse().map_err(E::custom)
            }
        }
        decoder.deserialize_str(WireKindVisitor)
    }
}

