/// Binding-count admission, distinct from semantic result arity.
/// Only declared discardable results may omit their SSA binding.
#[inline]
pub fn opcode_accepts_result_count(opcode: OpCode, count: usize) -> bool {
    match opcode {
        OpCode::BoxVal => count <= 1,
        OpCode::UnboxVal => count <= 1,
        _ => opcode_fixed_result_count_table(opcode).is_none_or(|expected| count == expected),
    }
}

/// One instance-shape gate for result inference and every TIR consumer.
#[inline]
pub fn opcode_accepts_shape(opcode: OpCode, operands: usize, results: usize) -> bool {
    opcode_accepts_operand_count(opcode, operands) && opcode_accepts_result_count(opcode, results)
}

/// Result-indexed intrinsic types, independent of effect/scheduling purity.
/// Operand-dependent slots remain None; another result of the same opcode
/// can still have an exact type (for example an iterator status flag).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum OperandIndependentResultType {
    I64,
    F64,
    Bool,
    Str,
    None,
    Bytes,
    DynBox,
    ListDynBox,
    DictDynBoxDynBox,
    SetDynBox,
}

impl OperandIndependentResultType {
    #[inline]
    pub fn to_tir_type(self) -> TirType {
        match self {
            OperandIndependentResultType::I64 => TirType::I64,
            OperandIndependentResultType::F64 => TirType::F64,
            OperandIndependentResultType::Bool => TirType::Bool,
            OperandIndependentResultType::Str => TirType::Str,
            OperandIndependentResultType::None => TirType::None,
            OperandIndependentResultType::Bytes => TirType::Bytes,
            OperandIndependentResultType::DynBox => TirType::DynBox,
            OperandIndependentResultType::ListDynBox => TirType::List(Box::new(TirType::DynBox)),
            OperandIndependentResultType::DictDynBoxDynBox => {
                TirType::Dict(Box::new(TirType::DynBox), Box::new(TirType::DynBox))
            }
            OperandIndependentResultType::SetDynBox => TirType::Set(Box::new(TirType::DynBox)),
        }
    }
}

/// Operand-independent result type by opcode. EXHAUSTIVE over OpCode so new
