/// Counted-loop ordered-comparison role by opcode. The registry owns
/// Lt/Le/Gt/Ge membership, loop-direction polarity, and logical inverse;
/// counted_loop.rs owns SSA shape, constants, and trip-count arithmetic.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CountedLoopComparisonRole {
    None,
    DecreasingExclusive,
    DecreasingInclusive,
    IncreasingExclusive,
    IncreasingInclusive,
}

impl CountedLoopComparisonRole {
    #[inline]
    pub fn is_ordered(self) -> bool {
        !matches!(self, CountedLoopComparisonRole::None)
    }

    #[inline]
    pub fn requires_positive_step(self) -> bool {
        matches!(
            self,
            CountedLoopComparisonRole::IncreasingExclusive
                | CountedLoopComparisonRole::IncreasingInclusive
        )
    }

    #[inline]
    pub fn is_inclusive(self) -> bool {
        matches!(
            self,
            CountedLoopComparisonRole::IncreasingInclusive
                | CountedLoopComparisonRole::DecreasingInclusive
        )
    }
}

